// user.service.spec.ts
//
// Contract under test (UserService.create):
//   - looks up an existing user via repository.findOne(email)
//   - if one is found, it short-circuits and does NOT call repository.save
//   - otherwise it builds a new user and calls repository.save(user) exactly once

import { UserService } from './user.service';

describe('UserService', () => {
  let service: UserService;

  // Declared ONCE at describe scope -- shared by every test in this file.
  const mockRepository = {
    save: jest.fn(),
    findOne: jest.fn(),
  };

  // Wired up ONCE for the whole suite. Nothing between tests ever clears
  // mockRepository.save / mockRepository.findOne -- no beforeEach with
  // jest.clearAllMocks() or mockRepository.save.mockReset() exists here.
  beforeAll(() => {
    service = new UserService(mockRepository as any);
  });

  it('creates a user', async () => {
    mockRepository.findOne.mockResolvedValue(null);
    mockRepository.save.mockResolvedValue({ id: 1, email: 'ada@test.com' });

    await service.create({ email: 'ada@test.com', password: 'secret123' });

    expect(mockRepository.findOne).toHaveBeenCalledWith('ada@test.com');
    expect(mockRepository.save).toHaveBeenCalledTimes(1);
  });

  it('does not save when the user already exists', async () => {
    mockRepository.findOne.mockResolvedValue({
      id: 1,
      email: 'ada@test.com',
    });

    await service.create({ email: 'ada@test.com', password: 'secret123' });

    // mockRepository.save's call count from the previous test was never
    // reset, so this assertion sees the leftover call and fails -- unless
    // this test happens to run first, in which case it passes and the
    // OTHER test is the one that breaks instead.
    expect(mockRepository.save).not.toHaveBeenCalled();
  });
});
